  + '        placeholder="MM"\n'
  + '        type="month"\n'
  + '        value={internalMonth}\n'
  + '        onChange={setInternalMonth}\n'
  + '      />\n'
  + '      <span className={styles.datePickerInputDecorator}>-</span>\n'
