  + '    </InputBase>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'DatePicker.displayName = "DatePicker";\n'
  + '\n'
  + 'type DatePickerInputPartProps = {\n'
  + '  type: "year" | "month" | "day" | "hour" | "minute" | "second";\n'
