sourceCode['calendar-opener.tsx'] = ''
  + 'import type dayjs from "dayjs";\n'
  + 'import { CalendarDays } from "lucide-react";\n'
  + 'import type { FC } from "react";\n'
  + '\n'
  + 'import { Calendar } from "@/components/Calendar";\n'
  + 'import { Popover } from "@/components/Popover";\n'
  + '\n'
  + 'import styles from "./calendar-opener.module.scss";\n'
  + '\n'
  + 'type CalendarOpenerProps = {\n'
  + '  value?: dayjs.Dayjs | null;\n'
  + '  onChange?: (day: dayjs.Dayjs) => void;\n'
  + '};\n'
  + '\n'
  + 'const CalendarOpener: FC<CalendarOpenerProps> = (props) => {\n'
  + '  const { value, onChange } = props;\n'
  + '\n'
  + '  return (\n'
  + '    <Popover>\n'
  + '      <Popover.Trigger\n'
  + '        render={({ setRef, onToggle }) => (\n'
  + '          <button\n'
  + '            type="button"\n'
  + '            className={styles.calendarOpener}\n'
  + '            ref={setRef}\n'
  + '            onClick={onToggle}\n'
  + '          >\n'
  + '            <CalendarDays size={"60%"} />\n'
  + '          </button>\n'
  + '        )}\n'
  + '      />\n'
  + '      <Popover.Portal\n'
  + '        onClickOutside={({ closePortal }) => closePortal()}\n'
  + '        render={({ setRef, isOpen, floatingStyles, togglePortal }) =>\n'
  + '          isOpen && (\n'
  + '            <div ref={(el) => setRef(el)} style={floatingStyles}>\n'
  + '              <Calendar\n'
  + '                value={value}\n'
  + '                onChange={(v) => {\n'
  + '                  onChange?.(v);\n'
  + '                  togglePortal();\n'
  + '                }}\n'
  + '              />\n'
  + '            </div>\n'
  + '          )\n'
  + '        }\n'
  + '      />\n'
  + '    </Popover>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'export { CalendarOpener };\n'
  ;

